        assert t[1] in TAXONOMY_SUBJECTS, f"HAAD [{i}] invalid subject: {t[1]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"HAAD [{i}] invalid system: {t[2]}"
        assert t[5].startswith("https://"), f"HAAD [{i}] URL not https: {t[5]}"

